type memoryOTPStore struct {
	data map[string]string
}

func newMemoryOTPStore() *memoryOTPStore {
	return &memoryOTPStore{data: make(map[string]string)}
}

func (m *memoryOTPStore) Set(ctx context.Context, key string, value interface{}, expiration time.Duration) *redis.StatusCmd {
	val, _ := value.(string)
	m.data[key] = val
	return redis.NewStatusResult("OK", nil)
}

func (m *memoryOTPStore) Get(ctx context.Context, key string) *redis.StringCmd {
	val, ok := m.data[key]
	if !ok {
		return redis.NewStringResult("", redis.Nil)
	}
	return redis.NewStringResult(val, nil)
}

func (m *memoryOTPStore) Del(ctx context.Context, keys ...string) *redis.IntCmd {
	var removed int64
	for _, k := range keys {
		if _, ok := m.data[k]; ok {
			delete(m.data, k)
			removed++
		}
	}
	return redis.NewIntResult(removed, nil)
}

func TestAuthService_RequestOTPStoresHash(t *testing.T) {
	store := newMemoryOTPStore()

	user := &models.User{ID: uuid.New(), Phone: "+8801000000000"}
	cfg := &config.Config{OTPExpMinutes: 5, JWTSecret: "secret"}
	auth := NewAuthService(store, stubUserProvider{user: user}, cfg, &NotificationService{})

	if err := auth.RequestOTP(context.Background(), user.Phone); err != nil {
		t.Fatalf("request otp: %v", err)
	}

	key := "otp:" + user.Phone
	if _, ok := store.data[key]; !ok {
		t.Fatalf("expected otp hash stored in redis")
	}
}

func TestAuthService_VerifyOTP(t *testing.T) {
	store := newMemoryOTPStore()

	user := &models.User{ID: uuid.New(), Phone: "+8801888888888"}
	cfg := &config.Config{OTPExpMinutes: 5, JWTSecret: "secret"}
	auth := NewAuthService(store, stubUserProvider{user: user}, cfg, &NotificationService{})

	code := "123456"
	store.data["otp:"+user.Phone] = otp.Hash(code)

	token, u, err := auth.VerifyOTP(context.Background(), user.Phone, code)
	if err != nil {
		t.Fatalf("verify otp: %v", err)
	}
	if token == "" {
		t.Fatalf("expected token")
	}
	if u.ID != user.ID {
		t.Fatalf("expected user id %s got %s", user.ID, u.ID)
	}
	if _, ok := store.data["otp:"+user.Phone]; ok {
		t.Fatalf("expected otp key to be cleared")
	}
}

