package services

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/redis/go-redis/v9"

	"komponrodh/internal/config"
	"komponrodh/internal/models"
	"komponrodh/pkg/jwt"
	"komponrodh/pkg/otp"
)

type AuthService struct {
	store    OTPStore
	users    UserProvider
	cfg      *config.Config
	notifier *NotificationService
}

// OTPStore exposes minimal Redis operations needed for OTP flow.
type OTPStore interface {
	Set(ctx context.Context, key string, value interface{}, expiration time.Duration) *redis.StatusCmd
	Get(ctx context.Context, key string) *redis.StringCmd
	Del(ctx context.Context, keys ...string) *redis.IntCmd
}

// UserProvider exposes minimal user operations required for auth.
type UserProvider interface {
	GetOrCreateByPhone(ctx context.Context, phone string) (*models.User, error)
}

func NewAuthService(store OTPStore, users UserProvider, cfg *config.Config, notifier *NotificationService) *AuthService {
	return &AuthService{store: store, users: users, cfg: cfg, notifier: notifier}
}

func (s *AuthService) RequestOTP(ctx context.Context, phone string) error {
	phone = normalizePhone(phone)
	if phone == "" {
		return errors.New("phone is required")
	}

	code, err := otp.GenerateNumeric(6)
	if err != nil {
		return err
	}

	key := fmt.Sprintf("otp:%s", phone)
	if err := s.store.Set(ctx, key, otp.Hash(code), s.cfg.OTPDuration()).Err(); err != nil {
		return err
	}

	// Fire-and-forget SMS send (stub).
	go s.notifier.SendSMS(context.Background(), phone, fmt.Sprintf("Your Komponrodh code is %s", code))

	return nil
}

func (s *AuthService) VerifyOTP(ctx context.Context, phone, code string) (string, *models.User, error) {
	phone = normalizePhone(phone)
	if phone == "" || code == "" {
		return "", nil, errors.New("phone and otp required")
	}

	key := fmt.Sprintf("otp:%s", phone)
	hashed, err := s.store.Get(ctx, key).Result()
	if err != nil {
		return "", nil, errors.New("otp expired or invalid")
	}
	if !otp.Verify(hashed, code) {
		return "", nil, errors.New("otp mismatch")
	}

	user, err := s.users.GetOrCreateByPhone(ctx, phone)
	if err != nil {
		return "", nil, err
	}

	token, err := jwt.Generate(user.ID, s.cfg.JWTSecret, 60*24*time.Hour)
	if err != nil {
		return "", nil, err
	}

	// Clean OTP after successful verification.
	_ = s.store.Del(ctx, key).Err()

	return token, user, nil
}

func normalizePhone(phone string) string {
	phone = strings.TrimSpace(phone)
	phone = strings.ReplaceAll(phone, " ", "")
	return phone
}

import React, { useState } from 'react';
import { Text } from 'react-native';
import { useLocalSearchParams, useRouter } from 'expo-router';

import { Screen } from '@components/Screen';
import { InputField } from '@components/InputField';
import { PrimaryButton } from '@components/PrimaryButton';
import { InlineError } from '@components/InlineError';
import { useAuthStore } from '../state/auth';
import { colors, typography } from '@styles/theme';
import { registerPushToken } from '../lib/notifications';

export default function VerifyOTPScreen() {
  const params = useLocalSearchParams();
  const phone = (params.phone as string) || '';
  const [otp, setOtp] = useState('');
  const verifyOTP = useAuthStore((s) => s.verifyOTP);
  const loading = useAuthStore((s) => s.loading);
  const error = useAuthStore((s) => s.error);
  const router = useRouter();

  const handleVerify = async () => {
    await verifyOTP(phone, otp);
    if (!useAuthStore.getState().error) {
      const token = useAuthStore.getState().token;
      if (token) {
        registerPushToken(token);
      }
      router.replace('/(main)/home');
    }
  };

  return (
    <Screen>
      <Text style={{ fontSize: typography.heading, fontWeight: '800', color: colors.text, marginBottom: 16 }}>
        Enter OTP
      </Text>
      <Text style={{ marginBottom: 12, color: colors.subtext }}>Code sent to {phone}</Text>
      <InputField
        label="6-digit code"
        keyboardType="number-pad"
        value={otp}
        onChangeText={setOtp}
        maxLength={6}
        placeholder="123456"
      />
      <InlineError message={error} />
      <PrimaryButton label="Verify" onPress={handleVerify} loading={loading} disabled={otp.length !== 6} />
    </Screen>
  );
}

package controllers

import (
    "net/http"

    "github.com/gin-gonic/gin"

    "komponrodh/internal/middleware"
    "komponrodh/internal/services"
    "komponrodh/pkg/utils"
