// AuthController wires auth endpoints.
type AuthController struct {
    authService *services.AuthService
    userService *services.UserService
}

func NewAuthController(auth *services.AuthService, users *services.UserService) *AuthController {
    return &AuthController{authService: auth, userService: users}
}

func (ctl *AuthController) RequestOTP(c *gin.Context) {
    var req struct {
        Phone string `json:"phone" binding:"required"`
    }
    if err := c.ShouldBindJSON(&req); err != nil {
        utils.JSONError(c, http.StatusBadRequest, "phone is required")
        return
    }
    if err := ctl.authService.RequestOTP(c.Request.Context(), req.Phone); err != nil {
        utils.JSONError(c, http.StatusBadRequest, err.Error())
        return
    }
    c.JSON(http.StatusOK, gin.H{"message": "otp sent"})
}

func (ctl *AuthController) VerifyOTP(c *gin.Context) {
    var req struct {
        Phone string `json:"phone" binding:"required"`
        OTP   string `json:"otp" binding:"required"`
    }
    if err := c.ShouldBindJSON(&req); err != nil {
        utils.JSONError(c, http.StatusBadRequest, "phone and otp required")
        return
    }

    token, user, err := ctl.authService.VerifyOTP(c.Request.Context(), req.Phone, req.OTP)
    if err != nil {
        utils.JSONError(c, http.StatusBadRequest, err.Error())
        return
    }
    c.JSON(http.StatusOK, gin.H{"token": token, "user": user})
}

func (ctl *AuthController) GetMe(c *gin.Context) {
    userID, ok := middleware.UserIDFromContext(c)
    if !ok {
        utils.JSONError(c, http.StatusUnauthorized, "unauthorized")
        return
    }
    user, err := ctl.userService.GetByID(c.Request.Context(), userID)
    if err != nil {
        utils.JSONError(c, http.StatusNotFound, "user not found")
        return
    }
    utils.JSONOK(c, user)
}

func (ctl *AuthController) UpdateMe(c *gin.Context) {
    userID, ok := middleware.UserIDFromContext(c)
    if !ok {
        utils.JSONError(c, http.StatusUnauthorized, "unauthorized")
        return
    }

    var req struct {
        Name      string `json:"name"`
        AvatarURL string `json:"avatar_url"`
    }
    if err := c.ShouldBindJSON(&req); err != nil {
        utils.JSONError(c, http.StatusBadRequest, "invalid payload")
        return
    }

    user, err := ctl.userService.UpdateProfile(c.Request.Context(), userID, req.Name, req.AvatarURL)
    if err != nil {
        utils.JSONError(c, http.StatusBadRequest, err.Error())
        return
    }
    utils.JSONOK(c, user)
}

package middleware

import (
    "net/http"
    "strings"

    "github.com/gin-gonic/gin"
    "github.com/google/uuid"

    appjwt "komponrodh/pkg/jwt"
    "komponrodh/pkg/utils"
)

const ContextUserIDKey = "user_id"

// AuthMiddleware validates JWT bearer tokens and attaches the user ID to context.
func AuthMiddleware(secret string) gin.HandlerFunc {
    return func(c *gin.Context) {
        header := c.GetHeader("Authorization")
        if header == "" {
            utils.JSONError(c, http.StatusUnauthorized, "missing authorization header")
            c.Abort()
            return
        }

        parts := strings.SplitN(header, " ", 2)
        if len(parts) != 2 || !strings.EqualFold(parts[0], "Bearer") {
            utils.JSONError(c, http.StatusUnauthorized, "invalid authorization header")
            c.Abort()
            return
        }

        userID, err := appjwt.Parse(parts[1], secret)
        if err != nil || userID == uuid.Nil {
            utils.JSONError(c, http.StatusUnauthorized, "invalid token")
            c.Abort()
            return
        }

        c.Set(ContextUserIDKey, userID)
        c.Next()
    }
}

// UserIDFromContext fetches the authenticated user id from Gin context.
func UserIDFromContext(c *gin.Context) (uuid.UUID, bool) {
    val, ok := c.Get(ContextUserIDKey)
    if !ok {
        return uuid.Nil, false
    }
    id, ok := val.(uuid.UUID)
    return id, ok
}

