package jwt

import (
	"testing"
	"time"

	"github.com/google/uuid"
)

func TestGenerateAndParse(t *testing.T) {
	secret := "super-secret"
	userID := uuid.New()
	token, err := Generate(userID, secret, time.Hour)
	if err != nil {
		t.Fatalf("generate token: %v", err)
	}
	parsed, err := Parse(token, secret)
	if err != nil {
		t.Fatalf("parse token: %v", err)
	}
	if parsed != userID {
		t.Fatalf("expected %s got %s", userID, parsed)
	}
}

func TestParseInvalidSecret(t *testing.T) {
	secret := "super-secret"
	userID := uuid.New()
	token, err := Generate(userID, secret, time.Hour)
	if err != nil {
		t.Fatalf("generate token: %v", err)
	}
	if _, err := Parse(token, "wrong"); err == nil {
		t.Fatalf("expected error for wrong secret")
	}
}

