package db

import (
    "context"
    "fmt"
    "time"

    "github.com/jackc/pgx/v5/pgxpool"

    "komponrodh/internal/config"
)

// NewPostgres returns a configured pgx connection pool.
func NewPostgres(ctx context.Context, cfg *config.Config) (*pgxpool.Pool, error) {
    pgxCfg, err := pgxpool.ParseConfig(cfg.DBURL)
    if err != nil {
        return nil, fmt.Errorf("parse db url: %w", err)
    }
    pgxCfg.MinConns = 2
    pgxCfg.MaxConns = 10
    pgxCfg.MaxConnLifetime = time.Hour
    pgxCfg.MaxConnIdleTime = 10 * time.Minute

    pool, err := pgxpool.NewWithConfig(ctx, pgxCfg)
    if err != nil {
        return nil, fmt.Errorf("connect db: %w", err)
    }

    ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
    defer cancel()
    if err := pool.Ping(ctx); err != nil {
        pool.Close()
        return nil, fmt.Errorf("ping db: %w", err)
    }

    return pool, nil
}

package otp

import "testing"

func TestGenerateNumericLength(t *testing.T) {
	code, err := GenerateNumeric(6)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(code) != 6 {
		t.Fatalf("expected length 6, got %d", len(code))
	}
}

func TestHashVerify(t *testing.T) {
	code := "123456"
	hashed := Hash(code)
	if hashed == "" {
		t.Fatalf("hash should not be empty")
	}
	if !Verify(hashed, code) {
		t.Fatalf("hash should verify original code")
	}
	if Verify(hashed, "000000") {
		t.Fatalf("hash should not verify wrong code")
	}
}
